```python
import json
import os

def load(path: str) -> dict:
    """Load JSON data from a file, returning an empty dict if file doesn't exist."""
    if not os.path.exists(path):
        return {}
    with open(path) as f:
        data = json.load(f)
    return data

def save(path: str, data: dict) -> None:
    """Save JSON data to a file."""
    with open(path, "w") as f:
        json.dump(data, f)

def add_item(path: str, name: str, qty: int, price: float) -> None:
    """Add or update an item in the inventory."""
    data = load(path)
    if name in data:
        data[name]["qty"] += qty
    else:
        data[name] = {"qty": qty, "price": price}
    save(path, data)

def remove_item(path: str, name: str, qty: int) -> None:
    """Remove a quantity of an item from the inventory."""
    data = load(path)
    if name not in data:
        print("no such item")
        return
    data[name]["qty"] -= qty
    if data[name]["qty"] <= 0:
        del data[name]
    save(path, data)

def total_value(path: str) -> float:
    """Calculate the total monetary value of all items in the inventory."""
    data = load(path)
    total = 0
    for name in data:
        total += data[name]["qty"] * data[name]["price"]
    return total

def report(path: str) -> None:
    """Print a report of all items and their total value."""
    data = load(path)
    for name in sorted(data):
        print(name, data[name]["qty"], data[name]["price"])
    print("total", total_value(path))
