class Matrix:
    def __init__(self, rows):
        if not rows or not all(len(row) == len(rows[0]) for row in rows):
            raise ValueError("All rows must have the same length")
        self.rows = rows
        self.n = len(rows)
        self.m = len(rows[0])

    def add(self, other):
        if self.n != other.n or self.m != other.m:
            raise ValueError("Matrix dimensions must match for addition")
        out = []
        for i in range(self.n):
            row = []
            for j in range(self.m):
                row.append(self.rows[i][j] + other.rows[i][j])
            out.append(row)
        return Matrix(out)

    def mul(self, other):
        if self.m != other.n:
            raise ValueError("Number of columns in the first matrix must equal the number of rows in the second matrix for multiplication")
        out = []
        for i in range(self.n):
            row = []
            for j in range(other.m):
                s = 0
                for k in range(self.m):
                    s += self.rows[i][k] * other.rows[k][j]
                row.append(s)
            out.append(row)
        return Matrix(out)

    def transpose(self):
        out = []
        for j in range(self.m):
            row = []
            for i in range(self.n):
                row.append(self.rows[i][j])
            out.append(row)
        return Matrix(out)
```

### Key Changes:
- **`__init__`**: Validates that all rows have the same length and that the matrix is non-empty.
- **`add`**: Checks that both matrices have the same dimensions (`n` and `m`).
- **`mul`**: Checks that the number of columns of the first matrix (`self.m`) equals the number of rows of the second matrix (`other.n`), which is required for matrix multiplication.

Now, attempting to add or multiply matrices with mismatched dimensions will raise a `ValueError` with a descriptive message.

