class Matrix:
    def __init__(self, rows):
        if not rows or not all(len(row) == len(rows[0]) for row in rows):
            raise ValueError("All rows must have the same length")
        self.rows = rows
        self.n = len(rows)
        self.m = len(rows[0])

    def add(self, other):
        if self.n != other.n or self.m != other.m:
            raise ValueError(f"Cannot add matrices: dimensions mismatch. "
                           f"Left: ({self.n}x{self.m}), Right: ({other.n}x{other.m})")
        out = []
        for i in range(self.n):
            row = []
            for j in range(self.m):
                row.append(self.rows[i][j] + other.rows[i][j])
            out.append(row)
        return Matrix(out)

    def mul(self, other):
        if self.m != other.n:
            raise ValueError(f"Cannot multiply matrices: inner dimensions mismatch. "
                           f"Left: ({self.n}x{self.m}), Right: ({other.n}x{other.m})")
        out = []
        for i in range(self.n):
            row = []
            for j in range(other.m):
                s = 0
                for k in range(self.m):
                    s += self.rows[i][k] * other.rows[k][j]
                row.append(s)
            out.append(row)
        return Matrix(out)

    def transpose(self):
        out = []
        for j in range(self.m):
            row = []
            for i in range(self.n):
                row.append(self.rows[i][j])
            out.append(row)
        return Matrix(out)
